    final refusal = classifyImageCapError(finished.errorMessage)!;
    if (refusal.learnedCap < 1) return false;
    learnedCap = refusal.learnedCap;
    config.imageCapLatches?[imageCapLatchKey(
          config.model.provider,
          config.model.id,
