        'chatgpt-codex' => throw _codexVisionRefusal(),
        _ => 'https://api.openai.com/v1',
      };
  return Model(
    id: config.modelId,
    name: config.modelId,
    api: 'openai-completions',
    provider: config.providerKind,
    baseUrl: baseUrl,
    input: const ['text', 'image'],
    contextWindow: 128000,
    maxTokens: config.maxTokens,
